#BSUB -J atac_peak -n {{THREADS}} -q {{QUEUE}}
module load deepTools/3.5.1 MACS2/2.2.7.1 SAMtools/1.17
cd {{INPUT_DIR}} && mkdir -p peaks
for b in *.final.bam; do
  s=${b%.final.bam}
