  samtools index "${s}.shifted.bam"
  macs2 callpeak -t "${s}.shifted.bam" -f BAMPE -n "${s}" -g {{GENOME_SIZE}} --nomodel --shift -75 --extsize 150 -q 0.01 --outdir peaks
done

