#BSUB -J chiapet_loop -n {{THREADS}} -q {{QUEUE}}
cd {{INPUT_DIR}} && mkdir -p loops
# Mango 流程：PET 分类（自连/互连）→ 去 PCR 重复 → 峰调用 → PET cluster 显著性检验（stage 1-5 按 Mango 手册串行执行）
